CREATE TABLE roles (id serial PRIMARY KEY, name text NOT NULL UNIQUE, permissions jsonb NOT NULL DEFAULT '[]');
CREATE TABLE users (id serial PRIMARY KEY, username text NOT NULL UNIQUE, password text NOT NULL, full_name text NOT NULL, role_id integer NOT NULL REFERENCES roles, active boolean NOT NULL DEFAULT true, overrides jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE companies (id serial PRIMARY KEY, name text NOT NULL, currency text NOT NULL DEFAULT 'PKR' CHECK(currency='PKR'), approvals boolean NOT NULL DEFAULT true, locked_through date, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (user_id integer REFERENCES users, company_id integer REFERENCES companies, PRIMARY KEY(user_id,company_id));
CREATE TABLE contacts (id serial PRIMARY KEY, company_id integer NOT NULL REFERENCES companies, kind text NOT NULL CHECK(kind IN ('customer','vendor','employee')), name text NOT NULL, email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', tax_number text NOT NULL DEFAULT '', bank_details text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, UNIQUE(id,company_id));
CREATE TABLE projects (id serial PRIMARY KEY, company_id integer NOT NULL REFERENCES companies, name text NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(id,company_id));
CREATE TABLE accounts (id serial PRIMARY KEY, company_id integer NOT NULL REFERENCES companies, code text NOT NULL, name text NOT NULL, type text NOT NULL CHECK(type IN ('asset','liability','equity','revenue','expense')), purpose text NOT NULL DEFAULT 'general', currency text NOT NULL DEFAULT 'PKR', custodian_id integer, parent_id integer, active boolean NOT NULL DEFAULT true, UNIQUE(company_id,code), UNIQUE(id,company_id), FOREIGN KEY(custodian_id,company_id) REFERENCES contacts(id,company_id), FOREIGN KEY(parent_id,company_id) REFERENCES accounts(id,company_id));
CREATE UNIQUE INDEX system_account_unique ON accounts(company_id,purpose) WHERE purpose NOT IN ('general','bank','cash');
CREATE TABLE categories (id serial PRIMARY KEY, company_id integer NOT NULL REFERENCES companies, name text NOT NULL, parent_id integer, account_id integer NOT NULL, position integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, UNIQUE(id,company_id), FOREIGN KEY(parent_id,company_id) REFERENCES categories(id,company_id), FOREIGN KEY(account_id,company_id) REFERENCES accounts(id,company_id));
CREATE TABLE documents (id serial PRIMARY KEY, company_id integer NOT NULL REFERENCES companies, kind text NOT NULL, date date NOT NULL, amount numeric(20,2) NOT NULL CHECK(amount>0), currency text NOT NULL, rate numeric(20,8) NOT NULL CHECK(rate>0), base_amount numeric(20,2) NOT NULL CHECK(base_amount>0), description text NOT NULL, reference text NOT NULL DEFAULT '', due_date date, source_id integer, target_id integer, head_id integer, contact_id integer, project_id integer, category_id integer, related_id integer REFERENCES documents, other_company_id integer REFERENCES companies, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','rejected','posted','cancelled','reversed')), created_by integer NOT NULL REFERENCES users, approved_by integer REFERENCES users, posted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), extra jsonb NOT NULL DEFAULT '{}', UNIQUE(id,company_id), FOREIGN KEY(source_id,company_id) REFERENCES accounts(id,company_id), FOREIGN KEY(head_id,company_id) REFERENCES accounts(id,company_id), FOREIGN KEY(contact_id,company_id) REFERENCES contacts(id,company_id), FOREIGN KEY(project_id,company_id) REFERENCES projects(id,company_id), FOREIGN KEY(category_id,company_id) REFERENCES categories(id,company_id));
CREATE TABLE journals (id serial PRIMARY KEY, company_id integer NOT NULL REFERENCES companies, document_id integer NOT NULL REFERENCES documents, date date NOT NULL, reversal_of integer UNIQUE REFERENCES journals, UNIQUE(document_id,company_id,reversal_of));
CREATE UNIQUE INDEX one_original_posting ON journals(document_id,company_id) WHERE reversal_of IS NULL;
CREATE TABLE journal_lines (id serial PRIMARY KEY, journal_id integer NOT NULL REFERENCES journals, company_id integer NOT NULL REFERENCES companies, account_id integer NOT NULL, debit numeric(20,2) NOT NULL DEFAULT 0, credit numeric(20,2) NOT NULL DEFAULT 0, foreign_amount numeric(20,2) NOT NULL DEFAULT 0, currency text NOT NULL, contact_id integer REFERENCES contacts, project_id integer REFERENCES projects, CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)), FOREIGN KEY(account_id,company_id) REFERENCES accounts(id,company_id));
CREATE TABLE allocations (id serial PRIMARY KEY, document_id integer NOT NULL UNIQUE REFERENCES documents, related_id integer NOT NULL REFERENCES documents, amount numeric(20,2) NOT NULL CHECK(amount>0), base_amount numeric(20,2) NOT NULL CHECK(base_amount>0));
CREATE TABLE assets (id serial PRIMARY KEY, company_id integer NOT NULL REFERENCES companies, document_id integer NOT NULL UNIQUE REFERENCES documents, name text NOT NULL, cost numeric(20,2) NOT NULL, salvage numeric(20,2) NOT NULL DEFAULT 0, useful_life integer NOT NULL CHECK(useful_life>0), acquired date NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE attachments (id serial PRIMARY KEY, document_id integer NOT NULL REFERENCES documents, filename text NOT NULL, storage_key text NOT NULL UNIQUE, mime text NOT NULL, size integer NOT NULL, created_by integer NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit (id serial PRIMARY KEY, company_id integer REFERENCES companies, user_id integer NOT NULL REFERENCES users, action text NOT NULL, entity text NOT NULL, entity_id integer, before_value jsonb, after_value jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reconciliations (id serial PRIMARY KEY, company_id integer NOT NULL REFERENCES companies, account_id integer NOT NULL REFERENCES accounts, statement_date date NOT NULL, statement_balance numeric(20,2) NOT NULL, created_by integer NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reconciliation_lines (reconciliation_id integer REFERENCES reconciliations, line_id integer UNIQUE REFERENCES journal_lines, PRIMARY KEY(reconciliation_id,line_id));
CREATE INDEX ledger_account ON journal_lines(company_id,account_id);
CREATE INDEX document_company_date ON documents(company_id,date);
CREATE INDEX audit_company ON audit(company_id,created_at);
CREATE FUNCTION guard_journal() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE jid integer; total numeric; cnt integer;
BEGIN
 jid := COALESCE(NEW.journal_id,OLD.journal_id);
 SELECT COALESCE(sum(debit-credit),0),count(*) INTO total,cnt FROM journal_lines WHERE journal_id=jid;
 IF total<>0 OR cnt<2 THEN RAISE EXCEPTION 'Journal must contain balanced entries'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER balanced_journal AFTER INSERT OR UPDATE OR DELETE ON journal_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION guard_journal();
CREATE FUNCTION immutable_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Posted ledger is immutable; create a reversal'; END $$;
CREATE TRIGGER immutable_lines BEFORE UPDATE OR DELETE ON journal_lines FOR EACH ROW EXECUTE FUNCTION immutable_ledger();
CREATE TRIGGER immutable_journals BEFORE UPDATE OR DELETE ON journals FOR EACH ROW EXECUTE FUNCTION immutable_ledger();
